import{_ as r,C as o,c as a,o as n,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Skill types","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/setup/skill-types.md","filePath":"master/human-resources/employees/setup/skill-types.md","lastUpdated":1793074831000}'),i={name:"master/human-resources/employees/setup/skill-types.md"};function d(g,e,p,h,k,u){const l=o("ImagePopup");return n(),a("div",null,[e[0]||(e[0]=t('<h1 id="skill-types" tabindex="-1">Skill types <a class="header-anchor" href="#skill-types" aria-label="Permalink to &quot;Skill types&quot;">​</a></h1><p>Skill types organise what your people can do. A skill type is a group, such as Soft Skills. It holds skills (Communication) and levels (Beginner, Expert). You build this list once. After that, you add skills to employees by picking from it.</p><blockquote><p><strong>In simple words:</strong> A skill type is a folder. It holds the skills and the grades you can give for them.</p></blockquote><p>Open <code>Employees → Configurations → Skill Types</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has two tabs: <strong>All</strong> and <strong>Archived</strong>. The tab labels show a count. Seven types are included. Columns are <strong>Skill Type</strong>, <strong>Color</strong> and <strong>Skills</strong>. Skills appear as small badges.</p>',6)),s(l,{src:"/images1/employees/set_skilltype_list.png",alt:"Skill Types list with All and Archived tabs showing Languages, Soft Skills and IT"}),e[1]||(e[1]=t('<p>You can group the list by <strong>Name</strong>, <strong>Color</strong>, <strong>Created By</strong>, <strong>Status</strong>, <strong>Created At</strong> or <strong>Updated At</strong>. The <strong>Status</strong> filter shows active or inactive types.</p><h2 id="create-a-skill-type" tabindex="-1">Create a skill type <a class="header-anchor" href="#create-a-skill-type" aria-label="Permalink to &quot;Create a skill type&quot;">​</a></h2><p>This example makes a new type called <strong>Warehouse Skills</strong>. Aureus already includes <strong>Soft Skills</strong> and six other types.</p><ol><li>Open <code>Employees → Configurations → Skill Types</code>.</li><li>Click <strong>New Skill Type</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Warehouse Skills</code>.</li><li><strong><em>Color:</em></strong> Pick a colour from the list: <strong>Danger</strong>, <strong>Gray</strong>, <strong>Info</strong>, <strong>Success</strong> or <strong>Warning</strong>. For example, <strong>Success</strong> is green and <strong>Danger</strong> is red. A colour dot shows next to each name.</li><li><strong><em>Status:</em></strong> On by default. Switch it off to hide the type from new choices.</li></ul><p>A new type starts empty. After you create it, add skills and levels in the sections below.</p>',6)),s(l,{src:"/images1/employees/set_skilltype_form.png",alt:"Create Skill Types window with the name Warehouse Skills, a colour and Status on, with Create and Cancel buttons"}),e[2]||(e[2]=t('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><p>The <strong>View</strong> page of a skill type shows the same tabs as read only, with no <strong>New</strong> buttons. Add skills and levels from the <strong>Edit</strong> page.</p><h2 id="add-skills-and-levels" tabindex="-1">Add skills and levels <a class="header-anchor" href="#add-skills-and-levels" aria-label="Permalink to &quot;Add skills and levels&quot;">​</a></h2><p>Skills and levels live inside the skill type. Open the type with <strong>Edit</strong>. Two tabs appear below the form: <strong>Skills</strong> and <strong>Skill Levels</strong>.</p><h3 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h3><ol><li>Open the <strong>Skills</strong> tab.</li><li>Click <strong>New skill</strong>.</li><li>Type the <strong><em>Name:</em></strong> (required), for example <code>Forklift Operation</code>.</li><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> to add more.</li></ol>',6)),s(l,{src:"/images1/employees/set_skill_new.png",alt:"Create Skill window with only the Name field filled with Forklift Operation"}),e[3]||(e[3]=t('<h3 id="skill-levels" tabindex="-1">Skill levels <a class="header-anchor" href="#skill-levels" aria-label="Permalink to &quot;Skill levels&quot;">​</a></h3><ol><li>Open the <strong>Skill Levels</strong> tab.</li><li>Click <strong>New skill level</strong>.</li><li>Fill in the window.</li></ol><ul><li><strong><em>Name:</em></strong> Required. For example <code>Proficient</code>.</li><li><strong><em>Level:</em></strong> A number from 0 to 100. It is the percentage shown as a progress bar.</li><li><strong><em>Default Level:</em></strong> Switch it on to pre-select this level when someone adds a skill of this type.</li></ul>',3)),s(l,{src:"/images1/employees/set_level_new.png",alt:"Create Skill Level window with the name Proficient and level 65"}),e[4]||(e[4]=t('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><p>Only one level per type can be the default. Setting a new default clears the old one.</p><p>For Warehouse Skills, create three levels: <strong>Beginner</strong> at 25, <strong>Intermediate</strong> at 50 and <strong>Expert</strong> at 100.</p><p>The included <strong>Soft Skills</strong> type has five levels: <strong>Beginner</strong> 15 (the default level), <strong>Elementary</strong> 25, <strong>Intermediate</strong> 50, <strong>Advanced</strong> 80 and <strong>Expert</strong> 100. The <strong>Skill Levels</strong> table shows the columns <strong>Name</strong>, <strong>Level</strong> (a progress bar with the percent) and <strong>Default Level</strong> (a tick).</p>',4)),s(l,{src:"/images1/employees/set_levels_list.png",alt:"Skill Levels tab with the columns Name, Level and Default Level, listing levels with progress bars"}),e[5]||(e[5]=t('<h2 id="skill-types-included-in-aureus" tabindex="-1">Skill types included in Aureus <a class="header-anchor" href="#skill-types-included-in-aureus" aria-label="Permalink to &quot;Skill types included in Aureus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill type</th><th>Examples of skills</th><th>Levels</th></tr></thead><tbody><tr><td>Languages</td><td>French, Spanish, English</td><td>A1 to C2</td></tr><tr><td>Soft Skills</td><td>Communication, Teamwork, Leadership</td><td>Beginner, Elementary, Intermediate, Advanced, Expert</td></tr><tr><td>Programming Languages</td><td>Python, Java, Laravel</td><td>Beginner to Expert</td></tr><tr><td>IT</td><td>Web Development, Cloud Computing</td><td>Beginner to Expert</td></tr><tr><td>Marketing</td><td>Analytics, Email Marketing</td><td>L1 to L4</td></tr><tr><td>Accounts</td><td>Taxation &amp; Compliance, Tally</td><td>Learner to Professional</td></tr><tr><td>Quality Analyst</td><td>Manual Testing, API Testing</td><td>Learner to Professional</td></tr></tbody></table><h2 id="edit-archive-and-restore" tabindex="-1">Edit, archive and restore <a class="header-anchor" href="#edit-archive-and-restore" aria-label="Permalink to &quot;Edit, archive and restore&quot;">​</a></h2><p>Click <strong>Edit</strong> to change a type. Click <strong>Save changes</strong> to keep it. Click <strong>Delete</strong> to archive it. Use <strong>Restore</strong> on the <strong>Archived</strong> tab to bring it back.</p><h2 id="where-skills-are-used" tabindex="-1">Where skills are used <a class="header-anchor" href="#where-skills-are-used" aria-label="Permalink to &quot;Where skills are used&quot;">​</a></h2><ul><li>On an employee, the <strong>Add Skill</strong> button asks for a skill type, a skill and a level. The skill and level lists follow the type you pick. See <a href="./../employees/skills-and-resume.html">Skills and resume</a>.</li><li>The <a href="./../reporting/skills-report.html">Skills report</a> shows who has which skill.</li><li>Applicants and candidates in Recruitment use the same skill types.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reporting/skills-report.html">Skills report</a></li><li><a href="./../employees/skills-and-resume.html">Skills and resume</a></li><li><a href="./activity-plans.html">Activity plans</a></li></ul>',8))])}const y=r(i,[["render",d]]);export{c as __pageData,y as default};
